<style>
.unifco-language-switcher{display:inline-flex;align-items:center;gap:3px;padding:3px;background:#eef3f8;border:1px solid #dbe3ec;border-radius:9px}.unifco-language-switcher button{border:0;background:transparent;color:#1e315b;padding:6px 9px;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer}.unifco-language-switcher button.active{background:#1e315b;color:#fff}
/* Dashboard sidebar finishing pass */
.side .brand-logo-wrap{min-height:58px;padding:7px 10px;border-radius:10px}.side .brand-logo{width:38px;height:38px}.side .brand-wordmark b{font-size:15px;letter-spacing:.16em}.side .brand-wordmark small{font-size:6.5px}.side .side-collapse{top:16px;width:24px;height:24px;right:-6px}.side .side-search{margin:7px 0 8px}.side .quick-actions{margin:6px 0 9px}.side .quick-actions a:first-child{background:rgba(206,18,45,.92);border-color:rgba(255,255,255,.16)}.side .quick-actions a:first-child:hover{background:#e00d2d}.side .nav-section-label{margin-top:9px}.side .nav-group summary,.side .nav-home{min-height:34px}.side .nav-group summary:focus-visible,.side .nav-home:focus-visible,.side .nav-link:focus-visible,.side .quick-actions a:focus-visible{outline:2px solid rgba(255,255,255,.72);outline-offset:2px}.side .nav-group[open]>summary{background:#ffffff0c}.side .nav-group.active-group>summary{box-shadow:inset 2px 0 0 rgba(206,18,45,.85)}
html[dir="rtl"] body{direction:rtl}html[dir="rtl"] .main{text-align:right}html[dir="rtl"] table th,html[dir="rtl"] table td{text-align:right}html[dir="rtl"] .side{direction:rtl}html[dir="rtl"] .nav-home,html[dir="rtl"] .nav-link{border-left:0;border-right:3px solid transparent}html[dir="rtl"] .nav-home.active,html[dir="rtl"] .nav-link.active{border-right-color:#ce122d}html[dir="rtl"] .nav-group summary:after{margin-left:0;margin-right:auto;transform:rotate(180deg)}html[dir="rtl"] .nav-group[open] summary:after{transform:rotate(90deg)}html[dir="rtl"] .nav-children{margin-left:0;margin-right:27px;padding-left:0;padding-right:7px;border-left:0;border-right:1px solid #ffffff18}html[dir="rtl"] .side-search:before{left:auto;right:11px}html[dir="rtl"] .side-search input{padding-left:10px;padding-right:33px}html[dir="rtl"] .side-collapse{right:auto;left:-6px}
</style>
<script>
(function(){const D={'Operations Command Center':'مركز العمليات التشغيلية','Dashboard':'لوحة التحكم','Operations':'العمليات','Customers & Service':'العملاء والخدمات','Maintenance & Field Service':'الصيانة والخدمة الميدانية','Assets & EAM':'الأصول وإدارة الأصول المؤسسية','Inventory & Warehouses':'المخزون والمستودعات','Procurement':'المشتريات','Finance':'المالية','Projects & Manufacturing':'المشاريع والتصنيع','People':'الموارد البشرية','Insights & Platform':'التحليلات والمنصة','Insights & Intelligence':'التحليلات والذكاء','Administration':'الإدارة','CRM Overview':'نظرة عامة على العملاء','Maintenance Overview':'نظرة عامة على الصيانة','EAM Overview':'نظرة عامة على الأصول','Inventory Overview':'نظرة عامة على المخزون','Procurement Overview':'نظرة عامة على المشتريات','Finance Overview':'نظرة عامة على المالية','HR Overview':'نظرة عامة على الموارد البشرية','Asset Register':'سجل الأصول','Stock Balances':'أرصدة المخزون','Warehouse Control':'إدارة المستودع','Purchase Orders':'أوامر الشراء','Journals':'القيود اليومية','Roles & Permissions':'الأدوار والصلاحيات','Business':'الأعمال','Human Resources':'الموارد البشرية','Inventory':'المخزون','Warehouse & Field Inventory':'مخزون المستودعات والمواقع','CRM':'إدارة علاقات العملاء','Customer Management':'إدارة العملاء','Customers':'العملاء','New Customer':'عميل جديد','Customer Onboarding':'تسجيل العميل','Customer Contracts':'عقود العملاء','Service Requests':'طلبات الخدمة','Work Orders':'أوامر العمل','Projects':'المشاريع','Manufacturing':'التصنيع','Maintenance':'الصيانة','Enterprise Assets':'إدارة الأصول','Finance Core':'النظام المالي','Manufacturing Operations':'عمليات التصنيع','Maintenance & EAM Operations':'عمليات الصيانة وإدارة الأصول','Maintenance Operations':'عمليات الصيانة','Scheduling & Dispatch':'الجدولة والتوجيه','Technician Mobile':'تطبيق الفني','Platform':'المنصة','AI Assistant':'المساعد الذكي','Executive Reporting':'التقارير التنفيذية','Documents':'المستندات','Notifications':'الإشعارات','Approvals':'الموافقات','Audit Trail':'