o_language',l);const q=document.getElementById('side-nav-search');if(q)q.placeholder=l==='ar'?'بحث في القائمة…':'Search menu…';document.querySelectorAll('.unifco-language-switcher button').forEach(b=>b.classList.toggle('active',b.dataset.lang===l))}function m(){const u=document.querySelector('.user-name');if(!u||document.querySelector('.unifco-language-switcher'))return;const x=document.createElement('span');x.className='unifco-language-switcher';x.innerHTML='<button type="button" data-lang="ar">العربية</button><button type="button" data-lang="en">English</button>';u.insertAdjacentElement('afterend',x);x.onclick=e=>{const b=e.target.closest('button[data-lang]');if(b)set(b.dataset.lang)};document.documentElement.dataset.unifcoLang='en';x.querySelector('[data-lang="en"]').classList.add('active');if((localStorage.getItem('unifco_language')||'en')==='ar')set('ar')}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',m):m()})();
</script>
